def __str__(self):
    return str(self.heap)

# 交换索引i和j处的值
def swap(self, i, j):
    self.heap[i], self.heap[j] = self.heap[j], self.heap[i]

# 计算结点父结点的索引
def parent(self, index):
    return (index - 1) // 2

# 计算结点左子结点的索引
def left_child(self, index):
    return 2 * index + 1

